class Solution:
    def maxSubarraySumAfterOperation(self, nums: List[int], k: int) -> int:
        n = len(nums)
        def trunc(x): return x // k if x >= 0 else -((-x) // k)
        L = [0] * (n + 1); cur = 0
        for i in range(1, n + 1):
            cur = max(nums[i - 1], cur + nums[i - 1])
            L[i] = max(L[i - 1], cur)
        R = [0] * (n + 1); cur = 0
        for i in range(n - 1, -1, -1):
            cur = max(nums[i], cur + nums[i])
            R[i] = max(R[i + 1], cur)
        P = [0] * (n + 1); D = [0] * (n + 1)
        for i in range(n):
            P[i + 1] = P[i] + nums[i]
            D[i + 1] = D[i] + trunc(nums[i])
        ans = -float('inf')
        for l in range(n):
            for r in range(l + 1, n + 1):
                ans = max(ans, L[l] + k * (P[r] - P[l]) + R[r],
                               L[l] + (D[r] - D[l]) + R[r])
        return ans

